<script setup lang="ts">
import {useBoardDrag} from './useBoardDrag';
import {pmsWorkspaceHref} from './loading';
import {ref,onMounted,onUnmounted} from 'vue';import {pmsApi} from './api';import PmsMyWorkCard from './PmsMyWorkCard.vue';import PmsMyWorkIssue from './PmsMyWorkIssue.vue';import PmsMyWorkAssignees from './PmsMyWorkAssignees.vue';
const {target,start,over,leave,clear}=useBoardDrag();function drag(id:number|null){start(id);dragged.value=id;}const props=defineProps<{csrf?:string;permissions:string[];userId?:number|null}>();const data=ref<any>(null),error=ref(''),loading=ref(false),moving=ref(false),dragged=ref<number|null>(null),issue=ref<number|null>(null),assignment=ref<any>(null);const empty=()=>({project:'',sprint:'',workflow:'',assignee:''});const filters=ref(empty()),applied=ref(empty());let version=0,disposed=false;const can=(key:string)=>props.permissions.includes('*')||props.permissions.includes(key);
async function load(apply=false){if(apply){applied.value={...filters.value};const url=new URL(location.href);for(const [k,v] of Object.entries(applied.value))v?url.searchParams.set(k,v):url.searchParams.delete(k);history.replaceState(null,'',url);}const v=++version;loading.value=true;try{const d=await pmsApi('my-work?'+new URLSearchParams(applied.value));if(v!==version||disposed)return;data.value=d.data;const selected=String(d.data.selectedWorkflow?.id||'');if(!filters.value.workflow||filters.value.workflow===applied.value.workflow||!d.data.workflows.some((w:any)=>String(w.id)===filters.value.workflow))filters.value.workflow=selected;applied.value.workflow=selected;error.value='';}catch(e){if(v===version&&!disposed)error.value=(e as Error).message;}finally{if(v===version)loading.value=false;}}
async function reset(){filters.value=empty();await load(true);}async function drop(c:any){clear();if(!dragged.value||moving.value||!data.value?.selectedWorkflow||!can('task-status'))return;const id=dragged.value;dragged.value=null;moving.value=true;try{await pmsApi('tasks/'+id+'/board',props.csrf,'PATCH',{workflow_id:data.value.selectedWorkflow.id,workflow_column_id:c.id});await load();}catch(e){error.value=(e as Error).message;}finally{moving.value=false;}}
function changed(){if(!loading.value&&!moving.value)void load();}onMounted(()=>{const q=new URLSearchParams(location.search);for(const key of Object.keys(filters.value) as (keyof typeof filters.value)[])filters.value[key]=q.get(key)||'';applied.value={...filters.value};const id=Number(q.get('issue'));if(id>0)issue.value=id;void load();window.addEventListener('pms:changed',changed);});onUnmounted(()=>{disposed=true;version++;window.removeEventListener('pms:changed',changed);});
</script>
<template><div class="work-shell pms-my-work-screen"><div class="work-toolbar mb-3"><div><div class="text-muted small mb-1">WORKSPACE / ASSIGNED ISSUES</div><h3 class="mb-1">{{data?.canManageTeam&&applied.assignee?'Team member board':'My Work'}}</h3><div class="text-muted">{{data?.tasks.length||0}} issues across your accessible projects and sprints.</div></div><button class="btn btn-label-secondary" :disabled="loading" @click="reset"><i class="fa fa-rotate-left me-1"></i>Reset board</button></div><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><template v-if="loading&&!data" class="p-3" role="status"></template><div v-if="data" class="filter-card p-3 mb-3"><form class="row g-2 align-items-end" @submit.prevent="load(true)"><div class="col-md-3"><label class="form-label" for="work-project">Project</label><select id="work-project" v-model="filters.project" class="form-select"><option value="">All projects</option><option v-for="p in data.projects" :key="p.id" :value="String(p.id)">{{p.name}}</option></select></div><div class="col-md-3"><label class="form-label" for="work-sprint">Sprint</label><select id="work-sprint" v-model="filters.sprint" class="form-select"><option value="">All sprints and backlog</option><option v-for="s in data.sprints" :key="s.id" :value="String(s.id)">{{s.name}} - {{s.status.charAt(0).toUpperCase()+s.status.slice(1)}}</option></select></div><div v-if="data.workflows.length > 1" class="col-md-2"><label class="form-label" for="work-workflow">Workflow</label><select id="work-workflow" v-model="filters.workflow" class="form-select" :disabled="!data.workflows.length"><option v-if="!data.workflows.length" value="">No workflows available</option><option v-for="w in data.workflows" :key="w.id" :value="String(w.id)">{{w.name}}</option></select></div><div v-if="data.canManageTeam" class="col-md-2"><label class="form-label" for="work-assignee">Assignee</label><select id="work-assignee" v-model="filters.assignee" class="form-select"><option value="">Everyone</option><option v-for="u in data.assignees" :key="u.id" :value="String(u.id)">{{u.name}}</option></select></div><div class="col-md-2"><button class="btn btn-primary w-100" :disabled="loading"><i class="fa fa-filter me-1"></i>Apply filters</button></div></form></div><section v-if="data&&!data.selectedWorkflow" class="pms-my-work-empty" role="status"><span class="pms-my-work-empty-icon"><i class="ti ti-layout-kanban" aria-hidden="true"></i></span><h4>{{data.tasks.length?'Your work needs an active workflow':'No assigned work yet'}}</h4><p>{{data.tasks.length?'Your accessible tasks do not have an available active workflow. Ask your project manager to check the workflow setup.':'Tasks will appear here when work is assigned to you or your permitted team in this company scope.'}}</p><a v-if="can('department-edit')" class="button" :href="pmsWorkspaceHref('/pms?section=workflows')">Manage workflows</a></section><div v-else class="work-board"><section class="work-column" v-for="c in data?.selectedWorkflow?.columns" :key="c.id" :class="{'drag-over':target===c.id}" @dragover.prevent="over(c.id,$event)" @dragleave="leave(c.id,$event)" @drop.prevent="drop(c)"><div class="work-column-title"><span class="badge" :class="'bg-label-'+c.color">{{c.name}}</span><span class="column-count badge bg-white text-dark">{{data.statusCounts[c.id]||0}}</span></div><div class="work-list"><PmsMyWorkCard v-for="t in data.tasks.filter((t:any)=>t.workflow_column_id===c.id)" :key="t.id" :task="t" :class="{dragging:dragged===t.id}" :can-change-status="can('task-status')" :can-quick-assign="data.canQuickAssign" @open="issue=$event" @assign="assignment=$event" @drag="drag"/><div v-if="!data.tasks.some((t:any)=>t.workflow_column_id===c.id)" class="work-empty">No assigned issues</div></div></section></div></div><PmsMyWorkIssue v-if="issue" :id="issue" :csrf="csrf" :permissions="permissions" :user-id="userId" @close="issue=null" @updated="load()"/><PmsMyWorkAssignees v-if="assignment" :task="assignment" :users="data.assignees" :csrf="csrf" @close="assignment=null" @updated="load()"/></template>

<style scoped>
.pms-my-work-empty{display:flex;flex-direction:column;align-items:center;gap:14px;padding:48px 24px;text-align:center;border:1px solid var(--pms-border);border-radius:14px;background:var(--pms-surface);margin-top:18px}.pms-my-work-empty-icon{display:grid;place-items:center;width:48px;height:48px;border-radius:12px;background:var(--pms-primary-soft);color:var(--pms-primary)}.pms-my-work-empty h4{font-size:18px;margin:0}.pms-my-work-empty p{max-width:480px;margin:0;color:var(--pms-muted);font-size:13px;line-height:1.7}
</style>
